{"CommandLine":"$logFile = "c:\Users\andre\OneDrive\Desktop\xview\programa perfecto\BITACORA_EN_VIVO_EXE.log"
$lastLen = 0
if (Test-Path $logFile) { $lastLen = (Get-Item $logFile).Length }

Write-Host "[MONITOR ACTIVO] Monitoreando instancia activa de PROGRAMA_PERFECTO_XVIEW_B866V2.exe (PID=5376)..."

$missingCount = 0
while ($true) {
    if (Test-Path $logFile) {
        $item = Get-Item $logFile
        if ($item.Length -gt $lastLen) {
            $fs = [System.IO.File]::Open($logFile, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
            $fs.Seek($lastLen, [System.IO.SeekOrigin]::Begin) | Out-Null
            $sr = New-Object System.IO.StreamReader($fs, [System.Text.Encoding]::UTF8)
            $newText = $sr.ReadToEnd()
            $sr.Close()
            $fs.Close()
            $lastLen = $item.Length
            if ($newText) {
                Write-Host -NoNewline $newText
            }
        }
    }

    $procs = Get-Process -Name "PROGRAMA_PERFECTO_XVIEW_B866V2" -ErrorAction SilentlyContinue
    if (-not $procs) {
        $missingCount++
        if ($missingCount -ge 16) {
            Write-Host "[FIN DE SESION] El usuario cerro definitivamente PROGRAMA_PERFECTO_XVIEW_B866V2.exe."
            break
        }
    } else {
        $missingCount = 0
    }
    Start-Sleep -Milliseconds 500
}","IsDaemon":true,"WaitMsBeforeAsync":2500,"toolSummary":"Monitor active PROGRAMA_PERFECTO_XVIEW_B866V2.exe session"}
